package org.matchlab.academic_net.di

import me.tatarka.inject.annotations.Component
import me.tatarka.inject.annotations.KmpComponentCreate
import org.matchlab.academic_net.AppDependencies
import org.matchlab.academic_net.feature.collaborators.domain.RoleRequirementProvider
import org.matchlab.academic_net.feature.projects.domain.ProjectsRepository

/**
 * Composition root of the app, generated by kotlin-inject. It is the only place that knows which
 * data source stands behind each repository (see [MockDataSourcesModule]).
 */
@AppScope
@Component
internal abstract class AppComponent :
    MockDataSourcesModule,
    ProjectsModule,
    ChatsModule,
    CollaboratorsModule,
    ProjectSearchModule,
    FeedModule {
    /** What `AppNavHost` hands to the screens of every feature. */
    abstract val dependencies: AppDependencies

    // Exposed so a test can check that the features share one repository.
    abstract val projectsRepository: ProjectsRepository
    abstract val roleRequirements: RoleRequirementProvider
}

/** Creates the component; the implementation is generated for each target. */
@KmpComponentCreate
internal expect fun createAppComponent(): AppComponent
